#!/usr/bin/env bash

###################################################################################
# Arc: normalise optionalDVNCount to 255 on the 6 existing pathways
###################################################################################
# Arc's UpOFT owner AND endpoint delegate are the deployer EOA
# 0x6E3dadcAf328ebB58753e89a3e589F5C5e988dF8 (keystore account "v2-supervaults"),
# not a Safe, so this leg is signed locally instead of through a multisig.
#
# Rewrites Arc's ULN config for Ethereum, Base, BSC, HyperEVM, Flare and RH to
# (20, 4, 255, 0, [Arc's 4 live DVNs], []). Confirmations, required DVN count and
# the DVN set are UNCHANGED; only optionalDVNCount moves 0 -> 255.
#
# Usage:
#   bash script/run/arc_optional_dvn_255.sh simulate
#   bash script/run/arc_optional_dvn_255.sh execute [account]
###################################################################################

set -euo pipefail

# REQUIRED: without it forge/cast falls back to foundry.toml's uint64-max gas_limit
# and the node rejects the tx with "lack of funds for max fee".
GAS_LIMIT="${GAS_LIMIT:-1000000}"

# NB: lowercase via tr, not ${VAR,,} — that is bash 4+ and macOS /bin/bash is 3.2.
lc() { printf '%s' "$1" | tr 'A-F' 'a-f'; }

MODE="${1:-}"
ACCOUNT="${2:-v2-supervaults}"
[[ "$MODE" == "simulate" || "$MODE" == "execute" ]] || {
    echo "Usage: $0 {simulate|execute} [account]" >&2; exit 1; }

[[ -f .env ]] && source .env
RPC="${ARC_RPC_URL:-https://rpc.mainnet.arc.io}"
if [[ -z "${ARC_RPC_URL:-}" ]]; then
    echo "WARNING: ARC_RPC_URL is not set, falling back to the public endpoint." >&2
    echo "         Every check below (owner/delegate gate, post-state assertion) is only" >&2
    echo "         as trustworthy as this RPC, and this leg is signed by a hot EOA." >&2
    echo "         Set ARC_RPC_URL to a trusted endpoint before executing." >&2
    if [[ "$MODE" == "execute" ]]; then
        read -r -p "         Continue on the public RPC anyway? (y/N): " _ans
        [[ "$_ans" == "y" || "$_ans" == "Y" ]] || { echo "aborted" >&2; exit 1; }
    fi
fi

OFT=0xA85abEf37c7e812ACA761b2BEC62fFF7f3728F1E
EP=0x6F475642a6e85809B1c36Fa62763669b1b48DD5B
SL=0xC39161c743D0307EB9BCc9FEF03eeb9Dc4802de7
RL=0xe1844c5D63a9543023008D332Bd3d2e6f1FE1043
EXPECTED_OWNER=0x6E3dadcAf328ebB58753e89a3e589F5C5e988dF8
EIDS=(30101 30184 30102 30367 30295 30416)
NAMES=(Ethereum Base BSC HyperEVM Flare RH)

# Arc's live DVN set, in the ascending order the ULN config requires. The post-state
# assertion compares the WHOLE tuple against this: a wrong-but-well-formed DVN set
# would pass a prefix check and an eth_call, and the DVN set is exactly what decides
# who can verify an inbound packet and mint UP on Arc.
EXPECTED_CFG="(20, 4, 255, 0, [0x9e0e95ede70f680f74480b510ff9f45c70e3da80, 0xa2447e5b58d357c49bf74b50b14421e6a100e525, 0xacde1f22eeab249d3ca6ba8805c8fee9f52a16e7, 0xfa9ba83c102283958b997adc8b44ed3a3cdb5dda], [])"

CD_SEND=""
CD_RECV=""

# ORDER: run this BEFORE transferring Arc ownership to a Safe. The check below
# fails closed once ownership moves, and Arc would then need a Safe runbook instead.
echo "=== Arc optionalDVNCount -> 255 (mode: $MODE) ==="
echo "RPC: ${RPC%%\?*}"

# Fail closed if ownership moved to a Safe since this script was written.
OWNER=$(cast call "$OFT" 'owner()(address)' --rpc-url "$RPC")
DELEGATE=$(cast call "$EP" 'delegates(address)(address)' "$OFT" --rpc-url "$RPC")
echo "owner=$OWNER delegate=$DELEGATE"
if [[ "$(lc "$OWNER")" != "$(lc "$EXPECTED_OWNER")" || "$(lc "$DELEGATE")" != "$(lc "$EXPECTED_OWNER")" ]]; then
    echo "ERROR: owner/delegate is no longer $EXPECTED_OWNER." >&2
    echo "       Ownership moved; use a Safe runbook instead of this script." >&2
    exit 1
fi

show() {
    echo ""
    echo "--- current app ULN config per pathway ($1) ---"
    for i in "${!EIDS[@]}"; do
        s=$(cast call "$SL" 'getAppUlnConfig(address,uint32)((uint64,uint8,uint8,uint8,address[],address[]))' \
              "$OFT" "${EIDS[$i]}" --rpc-url "$RPC" 2>/dev/null | head -1)
        r=$(cast call "$RL" 'getAppUlnConfig(address,uint32)((uint64,uint8,uint8,uint8,address[],address[]))' \
              "$OFT" "${EIDS[$i]}" --rpc-url "$RPC" 2>/dev/null | head -1)
        printf "  %-9s send=%s\n            recv=%s\n" "${NAMES[$i]}" "$s" "$r"
    done
}

show "before"

if [[ "$MODE" == "simulate" ]]; then
    echo ""
    echo "SIMULATION — no transactions sent. Calldata that would be submitted:"
    echo "  TX1 -> $EP  setConfig(oft, sendLib, 6 entries)"
    echo "  TX2 -> $EP  setConfig(oft, recvLib, 6 entries)"
    echo ""
    echo "Static-calling both to confirm they would not revert..."
    cast call "$EP" "$CD_SEND" --from "$EXPECTED_OWNER" --rpc-url "$RPC" >/dev/null \
        && echo "  TX1 OK" || { echo "  TX1 WOULD REVERT" >&2; exit 1; }
    cast call "$EP" "$CD_RECV" --from "$EXPECTED_OWNER" --rpc-url "$RPC" >/dev/null \
        && echo "  TX2 OK" || { echo "  TX2 WOULD REVERT" >&2; exit 1; }
    echo ""
    echo "Both calls succeed. Re-run with: $0 execute $ACCOUNT"
    exit 0
fi

echo ""
echo "Executing with account: $ACCOUNT"
for pair in "TX1:$CD_SEND" "TX2:$CD_RECV"; do
    label="${pair%%:*}"; cd="${pair#*:}"
    echo "  sending $label ..."
    h=$(cast send --account "$ACCOUNT" --rpc-url "$RPC" --gas-limit "$GAS_LIMIT" --json \
          "$EP" "$cd" | python3 -c "import json,sys; print(json.load(sys.stdin)['transactionHash'])")
    echo "    $label tx: $h"
done

echo ""
echo "--- asserting post-state on all ${#EIDS[@]} pathways ---"
fail=0
for i in "${!EIDS[@]}"; do
    for pair in "send:$SL" "recv:$RL"; do
        which="${pair%%:*}"; lib="${pair#*:}"
        got=$(cast call "$lib" 'getAppUlnConfig(address,uint32)((uint64,uint8,uint8,uint8,address[],address[]))' \
                "$OFT" "${EIDS[$i]}" --rpc-url "$RPC" 2>/dev/null | head -1)
        if [[ "$(lc "$got")" == "$(lc "$EXPECTED_CFG")" ]]; then
            printf "  ok    %-9s %s\n" "${NAMES[$i]}" "$which"
        else
            printf "  FAIL  %-9s %s -> %s\n" "${NAMES[$i]}" "$which" "$got"; fail=1
        fi
    done
done
echo ""
if [[ "$fail" == "0" ]]; then
    echo "SUCCESS: all ${#EIDS[@]} pathways report (20, 4, 255, 0, [4 DVNs], []) on both libraries."
else
    echo "ERROR: at least one pathway did not reach the expected config." >&2
    exit 1
fi
